from typing import List, Tuple

Vec = Tuple[int, ...]

def divides(a: Vec, b: Vec) -> bool:
    return len(a) == len(b) and all(ai <= bi for ai, bi in zip(a, b))

def dickson_basis(gens: List[Vec]) -> List[Vec]:
    """Minimal generating set of the monomial ideal generated by `gens`."""
    G = list(dict.fromkeys(gens))
    return sorted(g for g in G
                  if not any(h != g and divides(h, g) for h in G))
